s the bank exports them.\"\"\"\n\nfrom __future__ import annotations\n\nimport csv\nfrom dataclasses import dataclass\nfrom datetime import date\nfrom decimal import Decimal\n\n\n@dataclass(frozen=True)\nclass Transaction:\n    day: date\n    payee: str\n    category: str\n    amount: Decimal  # negative = money out\n\n    @property\n    def month(self) -> str:\n        return self.day.strftime(\"%Y-%m\")\n\n\ndef load_csv(path: str) -> list[Transaction]:\n    \"\"\"Read `date,payee,category,amount` rows; blank categories become \"Uncategorized\".\"\"\"\n    with open(path, newline=\"\", encoding=\"utf-8\") as handle:\n        return [\n            Transaction(\n                day=date.fromisoformat(row[\"date\"]),\n                payee=row[\"payee\"].strip(),\n                category=row[\"category\"].strip() or \"Uncategorized\",\n                amount=Decimal(row[\"amount\"]),\n            )\n            for row in csv.DictReader(handle)\n        ]\n\n\n=== test_report.py ===\nimport unittest\nfrom datetime import date\nfrom decimal import Decimal\n\nfrom ledger.model import Transaction\nfrom ledger.report import format_report, monthly_totals\n\n\ndef t(day: str, category: str, amount: str, payee: str = \"Test\") -> Transaction:\n    return Transaction(date.fromisoformat(day), payee, category, Decimal(amount))\n\n\nclass MonthlyTotalsTests(unittest.TestCase):\n    def test_splits_money_in_and_out(self):\n        totals = monthly_totals([t(\"2026-09-01\", \"Salary\", \"4200.00\"), t(\"2026-09-03\", \"Groceries\", \"-86.40\")])\n        self.assertEqual(totals[\"2026-09\"], {\"in\": Decimal(\"4200.00\"), \"out\": Decimal(\"86.40\")})\n\n    def test_months_come_out_oldest_first(self):\n        totals = monthly_totals([t(\"2026-10-02\", \"Rent\", \"-1850\"), t(\"2026-08-30\", \"Rent\", \"-1850\")])\n        self.assertEqual(list(totals), [\"2026-08\", \"2026-10\"])\n\n    def test_report_for_one_month(self):\n        report = format_report([t(\"2026-09-01\", \"S